    if open_count_1 != close_count_1 or open_count_2 != close_count_2:
        return 'No'

    sequences = [lst[0] + lst[1], lst[1] + lst[0]]

    for sequence in sequences:
        if is_balanced(sequence):
            return 'Yes'

    return 'No'

# Examples
print(match_parens(['()(', ')']))  # Output: 'Yes'
print(match_parens([')', ')']))     # Output: 'No'
